-- Unlike the NPC-cast Molten Front spells in 76_, these ARE player-
-- visible (override action-bar buttons), so a matching client
-- Custom/CSV DBC/Spell.csv row was also added (see 00_README client-side
-- notes) -- Spell.dbc recompiled/patched/synced separately.
-- =====================================================================

DELETE FROM `spell_dbc` WHERE `ID` IN (74934,74935,74937,74947);

